    conditions: "根要氧气。水把气排走，根就闷死。湿土再浇是火上浇油。 质地、降雨、灌溉和设施条件会改写法，邻县袋数不能直接抄。",
    plainExplain: "根要氧气。水把气排走，根就闷死。湿土再浇是火上浇油。 土是房间，肥是饭，根是嘴。房间坏了，嘴先伤，饭再香也吃不进。先改房间，再谈补饭。",
