    steps: [
      "下地先把整株、特写、土面三张对照看完。叶位、根和土面对不上，先停手，不要倒肥。",
      "秸秆还田、少裸露、坡地覆盖、轮耕。",
      "有机肥养肉。",
      "产量目标不要把土吃空。",
      "用量按测土、当地农技站和包装下限，宁少勿多，先小面积。改完看新叶新根，不要加倍。",
    ],
    fieldCheck: "地里这样确认：黑土层变薄，心土露出，土色发灰发硬。不是记忆里又黑又肥的那层。 对不上就测 0～20 厘米 pH、有机质和盐分，不要先倒肥。",
